/**
 * The totals of the post's targets on their networks, from each network post's latest numbers (`List posts on the networks` has them one by one): a number is there when at least one network gives a value it does not hide. Null until one of them has numbers. A target whose network post has none adds nothing, and that post's `metricsUnavailable` says why, such as a Facebook story that ended before Rizamo read it.
 */
export interface PostMetrics {
    /** Times it was played or shown on its networks, replays included: the main number. Missing where no network gives it, such as a Facebook Page read without insights, or every network hides it (`masked`). */
    views?: number | undefined;
    /** People who saw it, added up per network: one person on two networks counts twice. */
    reach?: number | undefined;
    /** Only from networks that still count impressions (not Instagram or Facebook since 2025). */
    impressions?: number | undefined;
    engagements?: number | undefined;
    likes?: number | undefined;
    comments?: number | undefined;
    shares?: number | undefined;
    saves?: number | undefined;
    clicks?: number | undefined;
    /** Accounts that followed from it: Instagram feed posts and stories, Facebook reels, TikTok posts. Missing unless a target gave a number the network did not hide. */
    follows?: number | undefined;
    /** Visits to the profile from it (`profile_visits` on a network post): Instagram feed posts and stories, TikTok posts. Missing unless a target gave a number the network did not hide. */
    profileVisits?: number | undefined;
    /** Engagements per 100 people reached, to two decimals, over the targets whose reach is above 0 (their engagements over their reach), as Analytics rates each post. A target with no reach, such as Threads or a Facebook reel, is left out. Missing when none has reach. It is not capped at 100: a post with more engagements than people reached, as when one person likes, comments and shares, rates above it. */
    engagementRate?: number | undefined;
    /** The numbers every target that has them hides because they are small (Meta: under 5), by the names above: missing from the totals rather than 0. Missing when none is. */
    masked?: string[] | undefined;
}
